UPDATE questions q JOIN activities a ON a.id=q.activity_id SET q.grading='exact' WHERE a.id=31 AND a.revision=1;
INSERT INTO answers(question_id,content,correct) SELECT q.id,'red',1 FROM questions q JOIN activities a ON a.id=q.activity_id WHERE a.id=31 AND a.revision=1 AND NOT EXISTS(SELECT 1 FROM answers an WHERE an.question_id=q.id AND an.content='red');
UPDATE questions q JOIN activities a ON a.id=q.activity_id SET q.grading='exact' WHERE a.id=32 AND a.revision=1;
